1	import type { Meta, StoryObj } from '@storybook/react-webpack5';
2	import { expect, userEvent, within } from 'storybook/test';
3	import React, { useState } from 'react';
4	import { ZimmSizeChipGroup } from './index';
5	import type { ZimmSizeChipValue } from './index';
6	
7	const meta: Meta<typeof ZimmSizeChipGroup> = {
8	  title: 'Commerce/ZimmSizeChipGroup',
9	  component: ZimmSizeChipGroup,
10	  parameters: { layout: 'padded' },
11	};
12	
13	export default meta;
14	type Story = StoryObj<typeof ZimmSizeChipGroup>;
15	
16	const SIZES: ZimmSizeChipValue[] = [
17	  { value: 'xs', label: 'XS' },
18	  { value: 's', label: 'S' },
19	  { value: 'm', label: 'M' },
20	  { value: 'l', label: 'L' },
21	  { value: 'xl', label: 'XL' },
22	];
23	
24	const DefaultExample = () => {
25	  const [selectedValue, setSelectedValue] = useState<string | undefined>('');
26	  return <ZimmSizeChipGroup values={SIZES} selectedValue={selectedValue} onSelect={setSelectedValue} />;
27	};
28	
29	/** Multi-size row, nothing selected initially — click a chip to see the live selection. */
30	export const Default: Story = {
31	  render: () => <DefaultExample />,
32	};
33	
34	/** A size pre-selected — its chip renders with the selected treatment and is the tab stop. */
35	export const WithSelection: Story = {
36	  args: {
37	    values: SIZES,
38	    selectedValue: 'm',
39	  },
40	};
41	
42	/** One size unavailable — shown disabled (not withheld), so the full size run stays visible. */
43	export const WithDisabledSize: Story = {
44	  args: {
45	    values: [
46	      { value: 'xs', label: 'XS' },
47	      { value: 's', label: 'S', isDisabled: true },
48	      { value: 'm', label: 'M' },
49	      { value: 'l', label: 'L' },
50	    ],
51	    selectedValue: 'm',
52	  },
53	};
54	
55	/** The size-chip Figma component set's other Type — a single non-interactive label, not a
56	 *  one-item radiogroup. */
57	export const OneSize: Story = {
58	  args: {
59	    values: [{ value: 'os', label: 'One Size' }],
60	  },
61	};
62	
63	const KeyboardNavigationExample = () => {
64	  const [selectedValue, setSelectedValue] = useState<string | undefined>('xs');
65	  return <ZimmSizeChipGroup values={SIZES} selectedValue={selectedValue} onSelect={setSelectedValue} />;
66	};
67	
68	/** Arrow-key navigation — ArrowRight moves both the roving tab stop and the selection. */
69	export const KeyboardNavigation: Story = {
70	  render: () => <KeyboardNavigationExample />,
71	  play: async ({ canvasElement }) => {
72	    const canvas = within(canvasElement);
73	    const first = canvas.getByRole('radio', { name: 'XS' });
74	    await userEvent.click(first);
75	    await userEvent.keyboard('{ArrowRight}');
76	    const second = canvas.getByRole('radio', { name: 'S' });
77	    await expect(second).toHaveFocus();
78	    await expect(second).toHaveAttribute('aria-checked', 'true');
79	  },
80	};
