80	/** A variant re-fetch in progress — ZimmProductPrice renders its own invisible placeholder,
81	 *  preserving the layout slot rather than collapsing it. */
82	export const LoadingPrice: Story = {
83	  args: {
84	    ...Default.args,
85	    currentPrice: undefined,
86	    isPriceLoading: true,
87	  },
